#!/usr/bin/env python3
import gzip, json
import pandas as pd

COMP = str.maketrans("ACGTNacgtn", "TGCANtgcan")
def revcomp(s):
    return s.translate(COMP)[::-1]

SCAF = "GTTTTAGAGCTA"            # scaffold downstream of spacer, sense amplicon
RCAF = "TAGCTCTAAAAC"            # revcomp scaffold (spacer follows it in the read)

lib = pd.read_csv("/task/input/library.tsv", sep="\t")
samples = pd.read_csv("/task/input/samples.tsv", sep="\t")
seqs = lib["sequence"].tolist()
idx = {s: i for i, s in enumerate(seqs)}
C = [[0] * len(samples) for _ in range(len(lib))]
qc = {}
for j, row in enumerate(samples.itertuples()):
    path = "/task/input/fastq/" + row.fastq_file
    total = mapped = 0
    with gzip.open(path, "rt") as fh:
        for n, line in enumerate(fh):
            if n % 4 != 1:
                continue
            if n % 4 == 1:
                total += 1
            read = line.rstrip()
            k = read.find(SCAF)
            if k >= 20:
                sp = read[k - 20:k]
            else:
                k = read.find(RCAF)
                if k >= 0 and k + 12 + 20 <= len(read):
                    sp = revcomp(read[k + 12:k + 32])
                else:
                    continue
            i = idx.get(sp)
            if i is not None:
                C[i][j] += 1
                mapped += 1
    qc[row.sample_id] = {"total_reads": total, "mapped_reads": mapped}

with open("/task/output/counts.tsv", "w") as out:
    out.write("sgRNA\tgene\t" + "\t".join(samples["sample_id"]) + "\n")
    for (sg, gene), c in zip(zip(lib["sgRNA"], lib["gene"]), C):
        out.write(sg + "\t" + gene + "\t" + "\t".join(map(str, c)) + "\n")
with open("/task/work/qc_raw.json", "w") as fh:
    json.dump(qc, fh)
print(json.dumps(qc, indent=1))
EOF

